/* dropdown menu: 200px, 6px padding, 32px rows */
#qaPop{width:200px!important;padding:6px!important;border:1px solid #D6DCE3!important;border-radius:10px!important;box-shadow:0 6px 18px rgba(15,23,42,.10)!important}
