#qaPop .mg.g-q{--gb:#FFF1E0;color:#9A3C00}
#qaPop.qm a,#qaPop.sm button[data-s]{display:flex;align-items:center;gap:8px;width:calc(100% - 12px)!important;height:36px!important;margin:0 6px!important;padding:8px 10px!important;border-radius:6px;font-size:12px!important;font-weight:500!important;line-height:1.2;color:#111827!important;text-decoration:none;text-align:left;background:transparent;border:0;cursor:pointer;box-sizing:border-box;transition:background-color .12s ease}
#qaPop.qm a:hover,#qaPop.sm button[data-s]:hover,#qaPop.sm a:hover{background:#F2F4F7}
#qaPop.sm a{display:flex;align-items:center;gap:8px;width:calc(100% - 12px)!important;height:36px!important;margin:0 6px 6px!important;padding:8px 10px!important;border-radius:6px;font-size:12px!important;line-height:1.2;text-decoration:none;box-sizing:border-box}
#qaPop.qm a>svg:first-child{flex:none;color:#C2410C}#qaPop.qm a>span{flex:1}#qaPop .chv{flex:none;color:#98A2B3;margin-left:auto}
